function update(dt){if(!started)return;let up=keys.w||keys.arrowup||touch.up,down=keys.s||keys.arrowdown||touch.down,left=keys.a||keys.arrowleft||touch.left,right=keys.d||keys.arrowright||touch.right,brake=keys[' ']||touch.brake;
