if(!missionDone&&player.car&&Math.hypot(player.x-marina.x,player.y-marina.y)<170){missionDone=true;player.money+=1500;document.getElementById('missionText').textContent='Chase complete! Your cash and reputation are up.';document.getElementById('objective').textContent='MISSION COMPLETE';setTimeout(()=>document.getElementById('objective').textContent='FREE ROAM',4000)}}
