function loop(t){let dt=Math.min(.033,(t-last)/1000||0);last=t;ctx.setTransform(DPR,0,0,DPR,0,0);ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(W/2-camera.x,H/2-camera.y);update(dt);draw();ctx.restore();document.getElementById('money').textContent='$'+String(player.money).padStart(6,'0');document.getElementById('wanted').textContent='★'.repeat(player.wanted)+'☆'.repeat(5-player.wanted);requestAnimationFrame(loop)}requestAnimationFrame(loop);
</script></body></html>
